{
 "lemmas": [
  {
   "statement": "The integral of x^2 over the square [-1,1]^2 is 4/3",
   "check": "integrate(integrate(x**2, (x, -1, 1)), (y, -1, 1)) - Rational(4, 3)"
  },
  {
   "statement": "The integral of x^2 y^2 over the square is 4/9",
   "check": "Eq(integrate(integrate(x**2 * y**2, (x, -1, 1)), (y, -1, 1)), Rational(4, 9))"
  },
  {
   "statement": "Every monomial with an odd exponent integrates to zero over the square by symmetry",
   "check": "integrate(integrate(x**3 * y**2, (x, -1, 1)), (y, -1, 1))"
  }
 ],
 "structure": "the centre, two points on the x axis at distance r, and four points (+-s, +-t): seven nodes, three weights, three parameters r, s, t",
 "hypotheses": [
  "with that orbit structure the six even moment equations up to degree 5 determine r^2 = 14/15, s^2 = 1/3, t^2 = 3/5",
  "a tensor product needs 9 points; the orbit rule needs 7"
 ]
}
```

